SELECT
id, tenant_id, session_id, session_event_id, timestamp, message_type, message_content,
message_data, synthetic, archived, metadata, version, active, created_by, created_at
FROM sys_ai_session_event e
WHERE e.session_id = #{sessionId}
AND e.active = 1
AND e.id < (
SELECT w.id
FROM sys_ai_session_event w
WHERE w.session_id = #{sessionId}
AND w.session_event_id = #{firstEventId}
)
AND e.id >= (
SELECT MAX(u.id)
FROM sys_ai_session_event u
WHERE u.session_id = #{sessionId}
AND u.active = 1
AND u.message_type = 'USER'
AND u.id < (
SELECT w.id
FROM sys_ai_session_event w
WHERE w.session_id = #{sessionId}
AND w.session_event_id = #{firstEventId}
)

    AND u.timestamp >= #{from}


    AND u.timestamp <= #{to}


    AND u.message_type IN

        #{messageType}



    AND u.synthetic = 0


    AND u.archived = 0

)

    AND e.timestamp >= #{from}


    AND e.timestamp <= #{to}


    AND e.message_type IN

        #{messageType}



    AND e.synthetic = 0


    AND e.archived = 0

ORDER BY e.id
